PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,plan TEXT NOT NULL DEFAULT 'free',balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0),retention INTEGER NOT NULL DEFAULT 90,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,superadmin INTEGER NOT NULL DEFAULT 0,totp TEXT,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members(tenant_id TEXT REFERENCES tenants(id),user_id TEXT REFERENCES users(id),role TEXT NOT NULL,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),tenant_id TEXT REFERENCES tenants(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS resources(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),kind TEXT NOT NULL,data TEXT NOT NULL,created TEXT NOT NULL,updated TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS resources_scope ON resources(tenant_id,kind);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,mime TEXT NOT NULL,pages INTEGER NOT NULL,size INTEGER NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mail(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,status TEXT NOT NULL,data TEXT NOT NULL,cost INTEGER NOT NULL,scheduled TEXT NOT NULL,tracking TEXT,provider_id TEXT,created TEXT NOT NULL,updated TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS mail_scope ON mail(tenant_id,status,scheduled);
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),amount INTEGER NOT NULL,reason TEXT NOT NULL,mail_id TEXT,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,tenant_id TEXT,user_id TEXT,action TEXT NOT NULL,detail TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS api_tokens(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,hash TEXT UNIQUE NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),email TEXT NOT NULL,role TEXT NOT NULL,hash TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS resets(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency(tenant_id TEXT,key TEXT,response TEXT NOT NULL,PRIMARY KEY(tenant_id,key));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checkouts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),amount INTEGER NOT NULL,credited INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS marketplace_products(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),active INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL,updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS marketplace_orders(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),user_id TEXT NOT NULL REFERENCES users(id),product_id TEXT NOT NULL REFERENCES marketplace_products(id),name TEXT NOT NULL,quantity INTEGER NOT NULL,total INTEGER NOT NULL,status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',request_key TEXT NOT NULL,created TEXT NOT NULL,updated TEXT NOT NULL,UNIQUE(tenant_id,request_key));
CREATE TABLE IF NOT EXISTS gateway_checkouts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),user_id TEXT NOT NULL REFERENCES users(id),provider TEXT NOT NULL,amount INTEGER NOT NULL,currency TEXT NOT NULL,email TEXT NOT NULL,credited INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
